import re, subprocess, sys

def run(*args):
    p=subprocess.run(['git',*args],capture_output=True,text=True,timeout=35,check=True)
    return p.stdout.strip()

try:
    if run('rev-parse','--is-shallow-repository')!='false':
        sys.exit('BLIND: history is shallow')
    records=run('log','--format=%B%x00','HEAD').split('\x00')
    count=0
    for message in records:
        lines=message.strip().splitlines()
        if not lines or not lines[0].startswith('agent-sandbox (auto): '):
            continue
        if not re.search(r'(?m)^Run: https://github\.com/chidionyema/idp/actions/runs/[0-9]+\s*$', message):
            continue
        if not re.search(r'(?m)^Greenlane-Head: [0-9a-f]{40}\s*$', message):
            continue
        count+=1
except (OSError,subprocess.SubprocessError) as exc:
    sys.exit('BLIND: cannot verify reachable main history: '+str(exc))
print('optimus.legion.missions_landed='+str(count))
